/**
 * LAUF-2-START (14.11.2026, Eric: "sicher das Save Game ... dann starte einfach
 * den neuen Lauf").
 *
 * Ersetzt den Spielstand dieses Browsers durch einen FRISCHEN Spielstand
 * (BN1, keine Source-Files, 8 GB home) und laedt die Seite neu. Der frische
 * Stand wurde am 14.11.2026 im Pruefstand (localhost:8799, eigener Origin)
 * angelegt, danach dort geloescht - die Kennung eac1fe0f5ad89 gibt es nur hier.
 * Eingebaut: Erics Einstellungen aus Lauf 1 (Remote API Port 12525 usw.),
 * AutoexecScript coldstart.js, und die Skripte, die coldstart.js braucht
 * (sonst startete beim Laden nichts, die Bruecke schiebt erst danach).
 *
 * Lauf 1 ist vorher gesichert (backups/ und C:/Users/erche/bitburner-backups-lauf1-ende).
 *
 * Aufruf: run lauf2start.js --jetzt   (ohne --jetzt nur Pruefung)
 * @param {NS} ns
 */
const SAVE_B64 = "";
const NEW_IDENTIFIER = "eac1fe0f5ad89";

export async function main(ns) {
  const log = (m) => {
    ns.tprint(m);
    ns.write("data/lauf2start.txt", new Date().toLocaleTimeString() + "  " + m + "\n", "a");
    if (ns.getHostname() !== "home") ns.scp("data/lauf2start.txt", "home");
  };
  const w = globalThis["win" + "dow"];
  const bytes = Uint8Array.from(atob(SAVE_B64), (c) => c.charCodeAt(0));
  // Pruefung: entpacken und Kennung lesen, bevor irgendetwas ueberschrieben wird
  const text = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
  const save = JSON.parse(text);
  const ident = JSON.parse(save.data.PlayerSave).data.identifier;
  if (ident !== NEW_IDENTIFIER) { log("ABBRUCH: Kennung " + ident + " statt " + NEW_IDENTIFIER); return; }
  log("Neuer Spielstand geprueft: Kennung " + ident + ", " + bytes.length + " Bytes.");
  if (!ns.args.includes("--jetzt")) { log("Nur Pruefung. Mit --jetzt wird ersetzt und neu geladen."); return; }
  w.onbeforeunload = null;
  const db = await new Promise((res, rej) => { const q = w.indexedDB.open("bitburnerSave"); q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); });
  await new Promise((res, rej) => {
    const t = db.transaction(["savestring"], "readwrite");
    t.objectStore("savestring").put(bytes, "save");
    t.oncomplete = () => res();
    t.onerror = () => rej(t.error);
  });
  db.close();
  w.onbeforeunload = null;
  w.location.reload();
}
